  looking_ahead = excluded.looking_ahead;

-- postpartum week 128: Vitamin E, where more isn't automatically better (CORRECTED — mother-centric rework)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   128,
   NULL,
   'Phase 5 of 6 — Beyond the first year',
   'Vitamin E, where more isn''t automatically better',
   '"Vitamin E is an antioxidant found in nuts, seeds, vegetable oils and leafy greens — these foods contribute vitamin E without needing to track it. High-dose vitamin E supplements are a different matter: they can raise bleeding risk, particularly with anticoagulant or antiplatelet medicines, so check the combined amount across any supplements you take with your pharmacist."',
   'Vitamin E is a fat-soluble antioxidant that helps protect your cells from everyday oxidative damage. It''s found across nuts, seeds, vegetable oils like sunflower and safflower, and leafy greens — a varied diet with some nuts, seeds or oil-based cooking helps most people meet their needs without any deliberate tracking, and dietary deficiency on its own is genuinely rare. High-dose vitamin E supplements can increase bleeding risk, particularly if you take an anticoagulant or antiplatelet medicine. This isn''t limited to a supplement taken on its own — the combined amount across a multivitamin and any separate vitamin E product can add up, so it''s worth checking the total with your pharmacist. There''s an established upper intake level for vitamin E, but staying under it isn''t a guarantee of safety for everyone. Ordinary food sources don''t carry this concern.',
   'If you manage diabetes or another condition affecting blood sugar: follow your own care team''s specific guidance on portions and timing — the A and B meal options here aren''t matched for carbohydrate content either. If you have PCOS: flexible, balanced eating across the week matters more than any single "PCOS diet" — there''s no special curative diet required, and the general guidance in this series applies to you too. If you take levothyroxine: follow your prescribed timing around meals, calcium-rich foods, and calcium or iron supplements — ask your pharmacist if you''re unsure about spacing. If you take a blood thinner, aspirin or another antiplatelet medication, or have upcoming surgery: check the combined amount of vitamin E across everything you take — including a multivitamin — with your pharmacist, and don''t start a high-dose vitamin E supplement without your clinician''s guidance; it can raise bleeding risk in this situation. Vitamin E from food isn''t a concern. These notes are general starting points, not condition-specific menus — the meal options below aren''t matched to any particular condition''s nutrient or carbohydrate targets. Individual guidance from your own care team always takes precedence.',
   'Meat, fish and eggs can all sit comfortably in a regular week''s meals here. If you are pregnant or breastfeeding and eat fish, FDA/EPA guidance recommends two to three adult servings weekly from its "Best Choices" list — about 113 g per serving before cooking. Follow local advisories. This is an option for fish eaters, not a requirement to add fish.',
   'Choose either option, not both — these are alternatives, not two separate meals. Repeating a combination you already enjoyed earlier in the week is completely fine. If nothing here appeals or you''d rather keep it simple, reheated dal, rice and curd is an option if it suits your dietary needs and any care plan you follow. The "if you''re still hungry" suggestions are suggestions, not limits — adjust everything to your own appetite; this week''s meals are meant to be adequate, not restrictive. The "A" options are vegetarian, prepared with vegetable stock or water rather than meat or fish stock, including this week''s regional dishes. Portions below are adjustable starting points, not maximum allowances — scale to your own appetite, activity and any care plan you follow. A cup means a standard 240ml measuring cup. Unless a dish says otherwise: rice or another cooked grain eaten on its own is one level cup (about 150g); a dal, bean or lentil curry eaten as its own dish is three-quarters of a cup cooked (about 150g); a roti is one medium piece; toast is 2 slices. In a mixed rice or grain dish, the meat, fish, paneer or legume component is about 75-100g of that ingredient (roughly a palm-sized piece, or half a cup of cooked legumes), counted separately from the grain itself. Paneer, tofu, meat or fish eaten as a dish''s main item is 75-100g cooked (a palm-sized piece), or two eggs — these are different foods with different nutrient content, and are not nutritionally interchangeable just because they share a similar portion size. Curd or milk is a small bowl or glass (150-200ml); a cooked vegetable side is about a cup; nuts or seeds used as a topping are about a tablespoon (roughly 10-15g). The meals contribute different nutrients across the day; each individual meal or snack does not need to include every food group. Choose varied meals through the day and include a dependable protein source and a dependable calcium source at more than one meal — curd, milk or paneer — rather than relying on trace amounts in mixed dishes or an optional extra. If you avoid dairy, include measured portions of calcium-fortified alternatives or calcium-set tofu, checking the label. Adults generally need about 1,000 mg of calcium a day, including while breastfeeding — a single measured serving is a helpful building block, not the whole day''s requirement on its own. Food choices alone don''t rule out a need for supplementation — ask your own clinician what''s right for you. This week''s meals draw on Rampuri and Rohilkhandi cooking (the Rampur region of western Uttar Pradesh) — mild Nawabi kormas finished with a cashew-almond gravy, seekh kebabs, and nut-forward dals. If a regional dish is unfamiliar or unavailable, choose a familiar alternative with a similar nutritional role: dal or beans for a legume dish, a suitable protein source for a protein dish, and vegetables for a vegetable side. Keep the grain portion and any planned calcium source. These swaps are not nutritionally identical.',
   '[{"day_number": 1, "title": "Anchor", "notes": "Vitamin E is a fat-soluble antioxidant that helps protect your cells from everyday oxidative damage. It''s found in nuts, seeds, vegetable oils like sunflower and safflower, and leafy greens — most people eating a varied diet with some nuts, seeds or oil-based cooking get enough without any special effort.", "breakfast_a": "Vegetable korma, mixed vegetables in a cashew-almond gravy with a measured 1/2 cup cooked lentils (1 cup korma) with roti (2 pieces) and a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2) with sunflower-seed paratha (2 pieces) and a glass of milk (200ml)", "lunch_a": "Rampuri dal, spiced lentils finished with a nut-and-cream tempering (1 cup, includes a measured 1/2 cup cooked lentils) with rice (1 cup cooked) and a spinach sabzi", "lunch_b": "Chicken Rampuri korma, almond-and-cashew gravy (100g chicken) with rice (1 cup cooked) and a spinach sabzi", "nourishment_break_a": "A small bowl of curd (150g) with roasted sunflower seeds (15g)", "nourishment_break_b": "A glass of milk (200ml) with roasted almonds (15g) and a piece of seasonal fruit", "dinner_a": "Roti (2 pieces) with a rajma (3/4 cup) and a beans sabzi", "dinner_b": "Paneer Rampuri korma (100g paneer) with roti (2 pieces) and a carrot sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 2, "title": "Everyday sources, without needing a supplement", "notes": "A tablespoon of sunflower or safflower oil used in cooking, a small handful of almonds or sunflower seeds, or a serving of spinach or another leafy green all add up across the week — vitamin E doesn''t usually need a dedicated dish or a supplement on top of a varied diet.", "breakfast_a": "Spinach-and-lentil paratha (2 pieces, includes a measured 1/2 cup cooked lentils) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-spinach bhurji (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rampuri dal with a nut-and-cream tempering (1 cup, includes a measured 1/2 cup cooked lentils) with rice (1 cup cooked) and a squash sabzi", "lunch_b": "Seekh kebab, minced chicken skewers (100g chicken) with rice (1 cup cooked) and a squash sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a cup of cut papaya", "nourishment_break_b": "A glass of milk (200ml) with roasted peanuts (15g) and a piece of seasonal fruit", "dinner_a": "Roti (2 pieces) with a moong dal (3/4 cup) and a beans sabzi", "dinner_b": "Chicken Rampuri korma (100g chicken) with roti (2 pieces) and a pumpkin sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 3, "title": "If you take a high-dose vitamin E supplement", "notes": "A multivitamin''s vitamin E content on its own is usually modest, but added to a separate high-dose supplement — often marketed for skin, hair or antioxidant claims — the total can add up quickly. Check the combined amount rather than assuming a multivitamin is automatically fine to add another product on top of. Worth knowing: High-dose vitamin E supplements can increase bleeding risk, particularly if you take an anticoagulant or antiplatelet medicine. This applies to the combined amount across everything you take, not only a standalone vitamin E product — a multivitamin and a separate supplement both count toward the total. There''s an established upper intake level for vitamin E, but staying under it isn''t a guarantee of safety for everyone. If you take any vitamin E supplement at a meaningful dose, check the combined amount with your pharmacist.", "breakfast_a": "Vegetable korma with cashew-almond gravy and a measured 1/2 cup cooked lentils (1 cup korma) with roti (2 pieces) and a small bowl of curd (150g)", "breakfast_b": "Egg-and-onion paratha (2 eggs, 2 paratha) with a glass of milk (200ml)", "lunch_a": "Rajma, kidney bean curry (1 cup, includes a measured 1/2 cup cooked rajma) with rice (1 cup cooked) and a spinach sabzi", "lunch_b": "Fish curry, Rampuri-style (100g fish) with rice (1 cup cooked) and a spinach sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a guava", "nourishment_break_b": "A glass of milk (200ml) with roasted walnuts (15g) and a piece of seasonal fruit", "dinner_a": "Masoor dal khichdi with mixed vegetables (a measured 1/2 cup cooked rice, a measured 1/2 cup cooked masoor dal, and a separately measured 1/2 cup cooked vegetables; add water as needed, finished volume varies)", "dinner_b": "Paneer-and-beans curry, paneer with french beans and tomato (100g paneer) with roti (2 pieces) and a beetroot sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 4, "title": "Cooking oil is already doing some of the work", "notes": "The vegetable oil you already cook with contributes vitamin E, especially sunflower, safflower or wheat-germ oil — you don''t need a special oil just for this, but it''s worth knowing your everyday cooking already helps.", "breakfast_a": "Sunflower-seed-and-vegetable upma with a measured 1/2 cup cooked lentils (1 cup upma) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-vegetable sandwich (2 eggs, 2 slices bread) with a glass of milk (200ml)", "lunch_a": "Chana masala, chickpea curry (1 cup, includes a measured 1/2 cup cooked chana) with rice (1 cup cooked) and a cabbage sabzi", "lunch_b": "Mutton Rampuri korma (100g mutton) with rice (1 cup cooked) and a cabbage sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a pear", "nourishment_break_b": "A glass of milk (200ml) with roasted cashews (15g) and a piece of seasonal fruit", "dinner_a": "Roti (2 pieces) with a toor dal (3/4 cup) and a cauliflower sabzi", "dinner_b": "Chicken Rampuri seekh, spiced minced chicken skewers (100g minced chicken) with roti (2 pieces) and a spinach sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 5, "title": "An easy nut-and-seed addition, not a rule", "notes": "Adding a small handful of almonds, sunflower seeds or another nut or seed to one snack today is an easy way to add vitamin E alongside other nutrients — it isn''t something to do at every meal, and your usual snacks the rest of the week are fine as they are.", "breakfast_a": "Roti (2 pieces) with a measured 1/2 cup cooked lentils and vegetables (1 cup dal-vegetable mix) with a small bowl of curd (150g)", "breakfast_b": "Egg-and-tomato toast (2 eggs, 2 slices) with a glass of milk (200ml)", "lunch_a": "Rampuri dal with a nut-and-cream tempering (1 cup, includes a measured 1/2 cup cooked lentils) with rice (1 cup cooked) and a bottle-gourd sabzi", "lunch_b": "Seekh kebab, minced mutton skewers (100g mutton) with rice (1 cup cooked) and a bottle-gourd sabzi", "nourishment_break_a": "A small bowl of curd (150g) with a cup of cut watermelon", "nourishment_break_b": "A glass of milk (200ml) with a few dates and roasted almonds (15g)", "dinner_a": "Roti (2 pieces) with an urad dal (3/4 cup)", "dinner_b": "Egg-and-spinach curry (2 eggs) with roti (2 pieces) and a carrot sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 6, "title": "The pattern across your week matters, not one meal", "notes": "One meal without any nuts, seeds or oil-cooked vegetables doesn''t meaningfully change your vitamin E status — it''s the pattern of varied foods across the week, not any single plate, that matters here.", "breakfast_a": "Vegetable korma with cashew-almond gravy and peas and a measured 1/2 cup cooked lentils (1 cup korma) with roti (2 pieces) and a small bowl of curd (150g)", "breakfast_b": "Egg bhurji with onion (2 eggs) with toast (2 slices) and a glass of milk (200ml)", "lunch_a": "Rampuri dal with a nut-and-cream tempering (1 cup, includes a measured 1/2 cup cooked lentils) with rice (1 cup cooked) and a cabbage-and-carrot sabzi", "lunch_b": "Chicken Rampuri korma (100g chicken) with rice (1 cup cooked) and a cabbage-and-carrot sabzi", "nourishment_break_a": "A small bowl of curd (150g) with an orange", "nourishment_break_b": "A glass of milk (200ml) with roasted pumpkin seeds (15g) and a piece of seasonal fruit", "dinner_a": "Chana dal, Rampuri-style with a nut-and-cream tempering (a measured 3/4 cup cooked chana dal) with rice (1 cup cooked) and a squash sabzi", "dinner_b": "Paneer-and-tomato curry (100g paneer) with roti (2 pieces) and a beans sabzi", "still_hungry": "A small bowl of curd (150g)"}, {"day_number": 7, "title": "A repeat-favourites day", "notes": "No forced choices today. Day 1''s combination is repeated below as a ready option — or swap in whichever meals from earlier in the week worked best for you. Looking back at this week, did you notice your everyday cooking oil, nuts or seeds already doing some of this work without you planning for it?", "breakfast_a": "Vegetable korma, mixed vegetables in a cashew-almond gravy with a measured 1/2 cup cooked lentils (1 cup korma) with roti (2 pieces) and a small bowl of curd (150g)", "breakfast_b": "Boiled eggs (2) with sunflower-seed paratha (2 pieces) and a glass of milk (200ml)", "lunch_a": "Rampuri dal, spiced lentils finished with a nut-and-cream tempering (1 cup, includes a measured 1/2 cup cooked lentils) with rice (1 cup cooked) and a spinach sabzi", "lunch_b": "Chicken Rampuri korma, almond-and-cashew gravy (100g chicken) with rice (1 cup cooked) and a spinach sabzi", "nourishment_break_a": "A small bowl of curd (150g) with roasted sunflower seeds (15g)", "nourishment_break_b": "A glass of milk (200ml) with roasted almonds (15g) and a piece of seasonal fruit", "dinner_a": "Roti (2 pieces) with a rajma (3/4 cup) and a beans sabzi", "dinner_b": "Paneer Rampuri korma (100g paneer) with roti (2 pieces) and a carrot sabzi", "still_hungry": "A small bowl of curd (150g)"}]'::jsonb,
   'What''s one small habit from this week — a food, a routine — that felt worth keeping, without needing to overhaul everything at once?',
   'The next set of weeks continues this series'' steady, one-topic-at-a-time approach to your own nutrition and wellbeing.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
